\begin{tikzpicture}

%% Outer Circle Parameters
\def\rOuter{4}
\def\xShiftOuter{0}
\def\yShiftOuter{0}

%% Inner Circle 1 Parameters
\def\rInner{1}
\def\xShiftInner{1}
\def\yShiftInner{1}

%% Inner Circle 2 Parameters
\def\rInnerTwo{1}
\def\xShiftInnerTwo{-1}
\def\yShiftInnerTwo{-1}	


	\pgfmathtruncatemacro{\negrOuter}{-1*\rOuter};
	\pgfmathtruncatemacro{\negrInner}{-1*\rInner};

