	xlabel = {$x$},
	ylabel = {$y$},
	xlabel style={below right},
	ylabel style={above left},
	every axis x label/.style={
	at={(ticklabel* cs:1.02)},anchor=west,},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
	]

\addplot[
name path=A, 
thick, 
color = orangepeel, 
domain=0:360,
samples = 200,
fill = lightblue, 
fill opacity=0.3,
postaction={decorate,
			decoration={
					markings,
						mark=between positions 0.14 and 1 step 0.25 with {\arrow[fill opacity=1,>=stealth, black, very thick]{>};}
					}}
]
({\rOuter*cos(\x)+\xShiftOuter},{\rOuter*sin{\x}+\yShiftOuter});


\addplot[name path=B, 
thick, 
color = orangepeel, 
domain=360:0, 
samples = 200,
fill=white,
postaction={decorate,
	decoration={
		markings,
		mark=between positions 0.14 and 1 step 0.33 with {\arrow[fill opacity=1,>=stealth, black, very thick]{>};}
}}
]
({\rInner*cos(\x)+\xShiftInner},{\rInner*sin{\x}+\yShiftInner});

