postaction={decorate,
	decoration={
		markings,
		mark=between positions 0.14 and 1 step 0.33 with {\arrow[fill opacity=1,>=stealth, black, very thick]{>};}
}}
]
({\rInnerTwo*cos(\x)+\xShiftInnerTwo},{\rInnerTwo*sin{\x}+\yShiftInnerTwo});


\node[deepskyblue, xshift=15pt, yshift=-15pt] at (axis cs: {1.15*\rOuter*cos(135)+\xShiftOuter},{1.15*\rOuter*sin(135)+\yShiftOuter}) {$D$};
\node[] at (axis cs: {1.15*\rOuter*cos(45)+\xShiftOuter},{1.15*\rOuter*sin(45)+\yShiftOuter}) {$C_1$};
\node[xshift=5pt, yshift=5pt] at (axis cs: {1.15*\rInner*cos(45)+\xShiftInner},{1.15*\rInner*sin(45)+\yShiftInner}) {$C_2$};
\node[xshift=-10pt, yshift=-10pt] at (axis cs: {1.15*\rInnerTwo*cos(235)+\xShiftInnerTwo},{1.15*\rInnerTwo*sin(2355)+\yShiftInnerTwo}) {$C_3$};



\end{axis}
\end{tikzpicture}
